/**
 * Pure rules for website/domain connections (provider 'website').
 *
 * A domain is only shown on a profile once its owner proved control of it by
 * publishing a DNS TXT record: `_serika.<domain>` (or `<domain>` itself) must
 * contain `serika-verification=<token>`, where the token is generated by the
 * server and stored in the row's metadata. Clients never write metadata, so
 * the verified flag cannot be forged through the API.
 */

/** Metadata key holding the challenge and its result. */
export const DOMAIN_VERIFICATION_KEY = 'domainVerification';

/** Sub-domain label users put the TXT record on. */
export const DOMAIN_TXT_HOST = '_serika';

/** Prefix of the TXT record value. */
export const DOMAIN_TXT_PREFIX = 'serika-verification=';

/** How many domains one user may link (verified or pending). */
export const MAX_DOMAINS_PER_USER = 10;

/** TLDs that never resolve on the public internet. */
const RESERVED_TLDS = new Set(['localhost', 'local', 'internal', 'test', 'example', 'invalid', 'onion', 'lan', 'home', 'arpa']);

export type DomainVerification = {
  token: string;
  verified: boolean;
  verifiedAt: string | null;
};

export type DomainChallenge = {
  type: 'TXT';
  /** Host label to enter at most DNS providers. */
  host: string;
  /** Fully-qualified record name. */
  name: string;
  value: string;
};

/**
 * Turn user input (`Example.com`, `https://www.example.com/about`) into a bare,
 * lower-case public hostname (`example.com`). Null when it is not a public
 * domain name (IPs, single labels, reserved TLDs, credentials in the URL).
 */
export function normalizeDomain(input: unknown): string | null {
  if (typeof input !== 'string') return null;
  let s = input.trim().toLowerCase();
  if (!s || s.length > 300) return null;
  if (!/^[a-z][a-z0-9+.-]*:\/\//.test(s)) s = `http://${s}`;
  let host: string;
  try {
    const url = new URL(s);
    if (url.protocol !== 'http:' && url.protocol !== 'https:') return null;
    if (url.username || url.password) return null;
    host = url.hostname; // IDNs come back as punycode
  } catch {
    return null;
  }
  host = host.replace(/\.$/, '');
  if (host.startsWith('www.')) host = host.slice(4);
  if (!host || host.length > 253) return null;
  const labels = host.split('.');
  if (labels.length < 2) return null;
  if (!labels.every((l) => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(l))) return null;
  const tld = labels[labels.length - 1];
  if (!/^(?:[a-z]{2,63}|xn--[a-z0-9-]{1,59})$/.test(tld)) return null; // also rejects IPv4
  if (RESERVED_TLDS.has(tld)) return null;
  return host;
}

/** A fresh random challenge token (hex, 32 chars). */
export function createDomainToken(): string {
  const bytes = new Uint8Array(16);
  globalThis.crypto.getRandomValues(bytes);
  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
}

export function newDomainMetadata(token: string): Record<string, unknown> {
  return { [DOMAIN_VERIFICATION_KEY]: { token, verified: false, verifiedAt: null } };
}

export function verifiedDomainMetadata(token: string, at: Date): Record<string, unknown> {
  return { [DOMAIN_VERIFICATION_KEY]: { token, verified: true, verifiedAt: at.toISOString() } };
}

/** The stored challenge, or null for rows created before verification existed. */
export function readDomainVerification(metadata: unknown): DomainVerification | null {
  if (!metadata || typeof metadata !== 'object') return null;
  const v = (metadata as Record<string, unknown>)[DOMAIN_VERIFICATION_KEY];
  if (!v || typeof v !== 'object') return null;
  const { token, verified, verifiedAt } = v as Record<string, unknown>;
  if (typeof token !== 'string' || !/^[a-f0-9]{16,64}$/.test(token)) return null;
  return {
    token,
    verified: verified === true,
    verifiedAt: typeof verifiedAt === 'string' ? verifiedAt : null,
  };
}

export function isVerifiedDomainConnection(conn: { provider?: unknown; metadata?: unknown } | null | undefined): boolean {
  return conn?.provider === 'website' && readDomainVerification(conn.metadata)?.verified === true;
}

export function domainChallenge(domain: string, token: string): DomainChallenge {
  return {
    type: 'TXT',
    host: DOMAIN_TXT_HOST,
    name: `${DOMAIN_TXT_HOST}.${domain}`,
    value: `${DOMAIN_TXT_PREFIX}${token}`,
  };
}

/**
 * Whether any TXT record (as returned by `resolveTxt`: each record is a list of
 * <=255-byte chunks) is exactly the expected verification value.
 */
export function txtRecordsContainToken(records: string[][], token: string): boolean {
  const expected = `${DOMAIN_TXT_PREFIX}${token}`;
  return records.some((chunks) => chunks.join('').trim().replace(/^"|"$/g, '').trim() === expected);
}

/** Websites only appear on a profile once verified; other providers are untouched. */
export function filterUnverifiedDomains<T extends { provider?: unknown; metadata?: unknown }>(rows: T[]): T[] {
  return rows.filter((c) => c.provider !== 'website' || isVerifiedDomainConnection(c));
}

export type OwnDomainStatus = {
  name: string;
  verified: boolean;
  verifiedAt: string | null;
  /** Null for legacy rows that never started verification. */
  challenge: DomainChallenge | null;
};

/** Verification status shown to the domain's owner (never to other users). */
export function ownDomainStatus(conn: { accountId: string; metadata?: unknown }): OwnDomainStatus {
  const v = readDomainVerification(conn.metadata);
  const name = v ? conn.accountId : normalizeDomain(conn.accountId) ?? conn.accountId;
  return {
    name,
    verified: v?.verified === true,
    verifiedAt: v?.verifiedAt ?? null,
    challenge: v ? domainChallenge(name, v.token) : null,
  };
}
